/*  Definitions for accessing register FTM_SC and its flags  */
#define FTM_SC(base)                 (__FTM_SC.tReg)                      ///< Status And Control
#define FTM_SC_PS(base)              (__FTM_SC.tBits.bfPs)                 ///< Prescale Factor Selection
#define FTM_SC_CLKS(base)            (__FTM_SC.tBits.bfClks)               ///< Clock Source Selection
#define FTM_SC_CPWMS(base)           (__FTM_SC.tBits.bfCpwms)              ///< Center-Aligned PWM Select
#define FTM_SC_RIE(base)             (__FTM_SC.tBits.bfRie)                ///< Reload Interrupt Enable
#define FTM_SC_RF(base)              (__FTM_SC.tBits.bfRf)           ///< Reload Flag
#define FTM_SC_TOIE(base)            (__FTM_SC.tBits.bfToie)               ///< Timer Overflow Interrupt Enable
#define FTM_SC_TOF(base)             (__FTM_SC.tBits.bfTof)          ///< Timer Overflow Flag
#define FTM_SC_PWMEN0(base)          (__FTM_SC.tBits.bfPwmen0)             ///< Channel 0 PWM enable bit
#define FTM_SC_PWMEN1(base)          (__FTM_SC.tBits.bfPwmen1)             ///< Channel 1 PWM enable bit
#define FTM_SC_PWMEN2(base)          (__FTM_SC.tBits.bfPwmen2)             ///< Channel 2 PWM enable bit
#define FTM_SC_PWMEN3(base)          (__FTM_SC.tBits.bfPwmen3)             ///< Channel 3 PWM enable bit
