/*  Address definitions for register FTM1_MODE  */
#define FTM1_MODE_OFFS__ADDR         0x0054U           ///< Offset address of SFR FTM1_MODE
#define FTM1_MODE__ADDR              0x40039054U       ///< Address of SFR FTM1_MODE

/*  Definitions of Bit-Masks  */
#define FTM1_MODE_FTMEN_MASK         0x00000001U                     ///< Mask for FTM1_MODE_FTMEN
#define FTM1_MODE_INIT_MASK          0x00000002U                     ///< Mask for FTM1_MODE_INIT
#define FTM1_MODE_WPDIS_MASK         0x00000004U                     ///< Mask for FTM1_MODE_WPDIS
