/*  Definitions of Bit-Positions  */
#define FTM1_MODE_FTMEN_POS          0x00U                           ///< Position for FTM1_MODE_FTMEN
#define FTM1_MODE_INIT_POS           0x01U                           ///< Position for FTM1_MODE_INIT
#define FTM1_MODE_WPDIS_POS          0x02U                           ///< Position for FTM1_MODE_WPDIS
#define FTM1_MODE_PWMSYNC_POS        0x03U                           ///< Position for FTM1_MODE_PWMSYNC
#define FTM1_MODE_CAPTEST_POS        0x04U                           ///< Position for FTM1_MODE_CAPTEST
