#define FTM1_MODE_FAULTIE_POS        0x07U                           ///< Position for FTM1_MODE_FAULTIE

/*  Definitions for accessing register FTM1_MODE and its flags  */
#define FTM1_MODE                    (__FTM1_MODE.tReg)               ///< Features Mode Selection
#define FTM1_MODE_FTMEN              (__FTM1_MODE.tBits.bfFtmen)      ///< FTM Enable
#define FTM1_MODE_INIT               (__FTM1_MODE.tBits.bfInit)       ///< Initialize The Channels Output
#define FTM1_MODE_WPDIS              (__FTM1_MODE.tBits.bfWpdis)      ///< Write Protection Disable
#define FTM1_MODE_PWMSYNC            (__FTM1_MODE.tBits.bfPwmsync)    ///< PWM Synchronization Mode
#define FTM1_MODE_CAPTEST            (__FTM1_MODE.tBits.bfCaptest)    ///< Capture Test Mode Enable
#define FTM1_MODE_FAULTM             (__FTM1_MODE.tBits.bfFaultm)     ///< Fault Control Mode
#define FTM1_MODE_FAULTIE            (__FTM1_MODE.tBits.bfFaultie)    ///< Fault Interrupt Enable

/** Type definition: MODE, Features Mode Selection */
typedef
    union _TFtm1_Mode {
        Treg32 tReg;
        struct _TTFtm1_ModeBits {
            TBit bfFtmen               : 1;  ///< FTM Enable
            TBit bfInit                : 1;  ///< Initialize The Channels Output
            TBit bfWpdis               : 1;  ///< Write Protection Disable
            TBit bfPwmsync             : 1;  ///< PWM Synchronization Mode
            TBit bfCaptest             : 1;  ///< Capture Test Mode Enable
            TBit bfFaultm              : 2;  ///< Fault Control Mode
            TBit bfFaultie             : 1;  ///< Fault Interrupt Enable
        } tBits;
}TFtm1_Mode;

extern volatile TFtm1_Mode __FTM1_MODE;


