#define RCM_SRIE_LOC                 (__RCM_SRIE.tBits.bfLoc)          ///< Loss-of-Clock Interrupt
#define RCM_SRIE_LOL                 (__RCM_SRIE.tBits.bfLol)          ///< Loss-of-Lock Interrupt
#define RCM_SRIE_WDOG                (__RCM_SRIE.tBits.bfWdog)         ///< Watchdog Interrupt
