#define RCM_SRIE_GIE                 (__RCM_SRIE.tBits.bfGie)          ///< Global Interrupt Enable
#define RCM_SRIE_LOCKUP              (__RCM_SRIE.tBits.bfLockup)       ///< Core Lockup Interrupt
#define RCM_SRIE_SW                  (__RCM_SRIE.tBits.bfSw)           ///< Software Interrupt
