#define MMDVSQ_CSR_DIV_MASK          0x40000000U                     ///< Mask for MMDVSQ_CSR_DIV
#define MMDVSQ_CSR_BUSY_MASK         0x80000000U                     ///< Mask for MMDVSQ_CSR_BUSY

