#define MMDVSQ_CSR_SRT_POS           0x00U                           ///< Position for MMDVSQ_CSR_SRT
#define MMDVSQ_CSR_USGN_POS          0x01U                           ///< Position for MMDVSQ_CSR_USGN
#define MMDVSQ_CSR_REM_POS           0x02U                           ///< Position for MMDVSQ_CSR_REM
#define MMDVSQ_CSR_DZE_POS           0x03U                           ///< Position for MMDVSQ_CSR_DZE
#define MMDVSQ_CSR_DZ_POS            0x04U                           ///< Position for MMDVSQ_CSR_DZ
#define MMDVSQ_CSR_DFS_POS           0x05U                           ///< Position for MMDVSQ_CSR_DFS
#define MMDVSQ_CSR_SQRT_POS          0x1DU                           ///< Position for MMDVSQ_CSR_SQRT
#define MMDVSQ_CSR_DIV_POS           0x1EU                           ///< Position for MMDVSQ_CSR_DIV
#define MMDVSQ_CSR_BUSY_POS          0x1FU                           ///< Position for MMDVSQ_CSR_BUSY

