#define MMDVSQ_CSR                   (__MMDVSQ_CSR.tReg)             ///< Control/Status Register
#define MMDVSQ_CSR_SRT               (__MMDVSQ_CSR.tBits.bfSrt)      ///< Start
#define MMDVSQ_CSR_USGN              (__MMDVSQ_CSR.tBits.bfUsgn)     ///< Unsigned calculation
#define MMDVSQ_CSR_REM               (__MMDVSQ_CSR.tBits.bfRem)      ///< REMainder calculation
#define MMDVSQ_CSR_DZE               (__MMDVSQ_CSR.tBits.bfDze)      ///< Divide-by-Zero-Enable
#define MMDVSQ_CSR_DZ                (__MMDVSQ_CSR.tBits.bfDz)  ///< Divide-by-Zero
#define MMDVSQ_CSR_DFS               (__MMDVSQ_CSR.tBits.bfDfs)      ///< Disable Fast Start
#define MMDVSQ_CSR_SQRT              (__MMDVSQ_CSR.tBits.bfSqrt)  ///< SQUARE ROOT
#define MMDVSQ_CSR_DIV               (__MMDVSQ_CSR.tBits.bfDiv)  ///< DIVIDE
#define MMDVSQ_CSR_BUSY              (__MMDVSQ_CSR.tBits.bfBusy)  ///< BUSY

